package main

import (
	"fmt"
	"sort"
	"strings"
)

func main() {
	var n int
	fmt.Scan(&n)
	var s string
	fmt.Scan(&s)

	// Mapping of each digit to the multiset of digits whose factorials multiply to the same product
	// We want to maximize the number, so we want as many large digits as possible
	// Key insight:
	// 0! = 1, 1! = 1 -> ignore
	// 2! = 2
	// 3! = 6
	// 4! = 24 = 4 * 6 = 4! * 3! -> but we want to express in terms of digits 2-9
	// Let's think about prime factorization of factorials:
	// 2! = 2
	// 3! = 6 = 2*3
	// 4! = 24 = 2^3 * 3
	// 5! = 120 = 2^3 * 3 * 5
	// 6! = 720 = 2^4 * 3^2 * 5
	// 7! = 5040 = 2^4 * 3^2 * 5 * 7
	// 8! = 40320 = 2^7 * 3^2 * 5 * 7
	// 9! = 362880 = 2^7 * 3^4 * 5 * 7

	// We want to find a multiset of digits (from 2-9) such that the product of their factorials equals the product of factorials of the input digits.
	// And we want to maximize the resulting number (so sort digits in descending order).

	// Strategy: For each digit in input, decompose it into "prime" digits (digits that cannot be further decomposed into smaller digits whose factorials multiply to the same).
	// Actually, let's think differently. We can replace certain digits with combinations of other digits:
	// 4! = 24. Can we get 24 from other digits? 4! = 4*6. But 4 and 6 are digits. However, 4! = 2^3 * 3. 
	// Let's see which digits can be broken down:
	// 4! = 24. 2! * 2! * 3! = 2*2*6 = 24. So 4 can be replaced by 3,2,2.
	// 6! = 720. 5! * 3! = 120 * 6 = 720. So 6 can be replaced by 5,3.
	// 8! = 40320. 7! * 2! = 5040 * 2 = 10080. No. 7! * 2! * 2! = 20160. No.
	// 8! = 40320. Let's check: 7! = 5040. 40320 / 5040 = 8. So 8! = 7! * 8. But 8 is a digit. So 8 can be replaced by 7,8? That doesn't help.
	// Wait, 8! = 40320. 7! * 2! * 2! * 2! = 5040 * 2 * 2 * 2 = 40320. So 8 can be replaced by 7,2,2,2.
	// 9! = 362880. 9! / 7! = 362880 / 5040 = 72. 72 = 2^3 * 3^2 = 3! * 3! * 2! * 2! * 2! = 6*6*2*2*2 = 288. No.
	// 9! = 362880. Let's see: 9! = 9 * 8 * 7 * 6 * 5 * 4 * 3 * 2 * 1.
	// Actually, let's use a different approach. We'll track the prime factorization of the total product, then greedily assign digits from 9 down to 2.

	// Prime factors we care about: 2, 3, 5, 7
	// For each digit d (2-9), compute the prime factorization of d!
	// Then for the input, compute the total prime factorization.
	// Then greedily pick the largest digit (9 down to 2) as many times as possible.

	// Factorials prime factorization:
	// 2!: 2^1
	// 3!: 2^1 * 3^1
	// 4!: 2^3 * 3^1
	// 5!: 2^3 * 3^1 * 5^1
	// 6!: 2^4 * 3^2 * 5^1
	// 7!: 2^4 * 3^2 * 5^1 * 7^1
	// 8!: 2^7 * 3^2 * 5^1 * 7^1
	// 9!: 2^7 * 3^4 * 5^1 * 7^1

	// Let's define the factorization for each digit
	type factors struct {
		two, three, five, seven int
	}

	fact := map[int]factors{
		2: {1, 0, 0, 0},
		3: {1, 1, 0, 0},
		4: {3, 1, 0, 0},
		5: {3, 1, 1, 0},
		6: {4, 2, 1, 0},
		7: {4, 2, 1, 1},
		8: {7, 2, 1, 1},
		9: {7, 4, 1, 1},
	}

	// Compute total factorization from input
	total := factors{0, 0, 0, 0}
	for _, c := range s {
		d := int(c - '0')
		if d >= 2 {
			f := fact[d]
			total.two += f.two
			total.three += f.three
			total.five += f.five
			total.seven += f.seven
		}
	}

	// Now greedily assign digits from 9 down to 2
	var result []int
	for d := 9; d >= 2; d-- {
		f := fact[d]
		// How many times can we use digit d?
		count := 1000000 // large number
		if f.two > 0 {
			count = min(count, total.two/f.two)
		}
		if f.three > 0 {
			count = min(count, total.three/f.three)
		}
		if f.five > 0 {
			count = min(count, total.five/f.five)
		}
		if f.seven > 0 {
			count = min(count, total.seven/f.seven)
		}

		for i := 0; i < count; i++ {
			result = append(result, d)
			total.two -= f.two
			total.three -= f.three
			total.five -= f.five
			total.seven -= f.seven
		}
	}

	// result should already be in descending order since we iterate from 9 to 2
	// Convert to string
	var sb strings.Builder
	for _, d := range result {
		sb.WriteRune(rune('0' + d))
	}
	fmt.Println(sb.String())
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
