import (
	"fmt"
	"sort"
	"strings"
)

func main() {
	var n int
	fmt.Scan(&n)
	var s string
	fmt.Scan(&s)

	// For each digit, we want to break it down into prime digits (2,3,5,7)
	// such that the product of factorials is preserved.
	// digit -> list of prime digits
	// 0 -> [] (but 0! = 1, so it doesn't contribute)
	// 1 -> [] (1! = 1)
	// 2 -> [2]
	// 3 -> [3]
	// 4 -> [3,2,2] because 4! = 24 = 3! * 2! * 2!
	// 5 -> [5]
	// 6 -> [5,3] because 6! = 720 = 5! * 3!
	// 7 -> [7]
	// 8 -> [7,3,2,2] because 8! = 40320 = 7! * 3! * 2! * 2!
	// 9 -> [7,3,3,2] because 9! = 362880 = 7! * 3! * 3! * 2!

	decomposition := map[byte][]byte{
		'0': {},
		'1': {},
		'2': {'2'},
		'3': {'3'},
		'4': {'3', '2', '2'},
		'5': {'5'},
		'6': {'5', '3'},
		'7': {'7'},
		'8': {'7', '3', '2', '2'},
		'9': {'7', '3', '3', '2'},
	}

	var result []byte
	for i := 0; i < len(s); i++ {
		d := s[i]
		result = append(result, decomposition[d]...)
	}

	// Sort in descending order to get the maximum number
	sort.Slice(result, func(i, j int) bool {
		return result[i] > result[j]
	})

	fmt.Print(strings.Join([]string{string(result)}, ""))
}
